-- =========================================================================\n-- V9: reemplazar booleanos y varchar-libres que enmascaraban estado\n-- =========================================================================\n\n-- 1) Añadir 'NONE' al enum compensation_state (para pagos sin compensación)\nALTER TYPE compensation_state ADD VALUE IF NOT EXISTS 'NONE' BEFORE 'OPEN';\n\n-- 2) payment.compensation_state varchar(30) -> enum\n--    Sanear valores inválidos antes del cast (defensivo)\nUPDATE payment SET compensation_state = 'NONE'\n WHERE compensation_state NOT IN (\n   'NONE','OPEN','EVIDENCE_VALIDATED','NOTIFIED','PLAN_SELECTED',\n   'EXECUTING','RECOVERED','DISPUTED','WRITTEN_OFF','REVERSED'\n ) OR compensation_state IS NULL;\nALTER TABLE payment\n  ALTER COLUMN compensation_state DROP DEFAULT,\n  ALTER COLUMN compensation_state TYPE compensation_state\n    USING compensation_state::compensation_state,\n  ALTER COLUMN compensation_state SET DEFAULT 'NONE';\n\n-- 3) payment_read_model.compensation_state varchar(30) -> enum\nUPDATE payment_read_model SET compensation_state = 'NONE'\n WHERE compensation_state NOT IN (\n   'NONE','OPEN','EVIDENCE_VALIDATED','NOTIFIED','PLAN_SELECTED',\n   'EXECUTING','RECOVERED','DISPUTED','WRITTEN_OFF','REVERSED'\n ) OR compensation_state IS NULL;\nALTER TABLE payment_read_model\n  ALTER COLUMN compensation_state DROP DEFAULT,\n  ALTER COLUMN compensation_state TYPE compensation_state\n    USING compensation_state::compensation_state,\n  ALTER COLUMN compensation_state SET DEFAULT 'NONE';\n\n-- 4) dispute_case_current.evidence_complete boolean -> enum evidence_status\nCREATE TYPE evidence_status AS ENUM (\n  'MISSING',              -- sin ningún documento\n  'PARTIAL',              -- faltan documentos del set mínimo\n  'PENDING_VERIFICATION', -- todos subidos, en revisión\n  'COMPLETE'              -- completos y verificados\n);\n\nALTER TABLE dispute_case_current\n  ADD COLUMN evidence_status evidence_status NOT NULL DEFAULT 'MISSING';\n\n-- Migración del valor booleano antiguo (best-effort: complete -> COMPLETE)\nUPDATE dispute_case_current\n   SET evidence_status = CASE\n     WHEN evidence_complete THEN 'COMPLETE'::evidence_status\n     ELSE 'MISSING'::evidence_status\n   END;\nALTER TABLE dispute_case_current DROP COLUMN evidence_complete;\n\n-- 5) deduction_log.reversed boolean -> enum deduction_status + reason\nCREATE TYPE deduction_status AS ENUM ('ACTIVE', 'REVERSED');\n\nALTER TABLE deduction_log\n  ADD COLUMN status deduction_status NOT NULL DEFAULT 'ACTIVE',\n  ADD COLUMN reversal_reason varchar(200);\n\nUPDATE deduction_log SET status = 'REVERSED' WHERE reversed = true;\nALTER TABLE deduction_log DROP COLUMN reversed;\n\n-- 6) finance_approval_status enum en dispute_case_current\n--    Reemplaza el booleano "requiresFinanceApproval" del DMN\nCREATE TYPE finance_approval_status AS ENUM (\n  'NOT_REQUIRED','REQUIRED','APPROVED','REJECTED'\n);\n\nALTER TABLE dispute_case_current\n  ADD COLUMN finance_approval_status finance_approval_status\n        NOT NULL DEFAULT 'NOT_REQUIRED',\n  ADD COLUMN finance_approval_reason varchar(200);\n\n-- =========================================================================\n-- Correcciones adicionales (bugs y gaps de la emisión anterior)\n-- =========================================================================\n\n-- a) Columnas que faltaban en compensation_case para el ciclo de vida completo\nALTER TABLE compensation_case\n  ADD COLUMN notified_at timestamptz,\n  ADD COLUMN plan_selected_at timestamptz,\n  ADD COLUMN executing_at timestamptz,\n  ADD COLUMN closed_at timestamptz,\n  ADD COLUMN contractual_basis text;\n\n-- b) Columnas para recovery_account: faltaba el "id del último evento aplicado"\nALTER TABLE recovery_account\n  ADD COLUMN last_event_id uuid,\n  ADD COLUMN last_event_version bigint;\n\n-- c) Columnas de auditoría que los servicios necesitan\nALTER TABLE dispute_case\n  ADD COLUMN created_by uuid;\n\n-- d) Asegurar que business_calendar tiene índices para la función\nCREATE INDEX IF NOT EXISTS idx_bc_lookup\n  ON business_calendar (jurisdiction_id, calendar_date, is_business_day);\n\n-- e) Semilla de tasas de interés legales para que el cálculo no falle\nINSERT INTO legal_interest_rate\n  (jurisdiction_id, effective_from, effective_to, annual_rate, source_reference)\nVALUES\n  ('MX_CDMX', '2025-01-01', NULL, 0.113100, 'DOF 2025'),\n  ('ES_MADRID', '2025-01-01', NULL, 0.032500, 'BOE 2025'),\n  ('US_TX', '2025-01-01', NULL, 0.075000, 'TX Finance Code 304')\nON CONFLICT DO NOTHING;